package main

import "math"

// Checked 64-bit arithmetic: each function reports ok == false when the exact
// result is not representable or the operation is undefined.

func checkedAdd(a, b int64) (int64, bool) {
	s := a + b
	// Overflow iff both operands share a sign that the sum does not.
	return s, (a^s)&(b^s) >= 0
}

func checkedSub(a, b int64) (int64, bool) {
	d := a - b
	// Overflow iff the operands differ in sign and the result's sign differs from a.
	return d, (a^b)&(a^d) >= 0
}

func checkedMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	p := a * b
	if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || p/b != a {
		return 0, false
	}
	return p, true
}

func checkedDiv(a, b int64) (int64, bool) {
	if b == 0 || (a == math.MinInt64 && b == -1) {
		return 0, false
	}
	return a / b, true
}

func checkedRem(a, b int64) (int64, bool) {
	if b == 0 {
		return 0, false
	}
	if b == -1 {
		return 0, true // MinInt64 % -1 is 0 mathematically.
	}
	return a % b, true
}

func checkedNeg(a int64) (int64, bool) {
	if a == math.MinInt64 {
		return 0, false
	}
	return -a, true
}

package main

import "math"

// op is an operator held on the evaluator's operator stack.
type op uint8

const (
	opAdd op = iota
	opSub
	opMul
	opDiv
	opRem
	opNeg
	opLParen
)

func (o op) precedence() int {
	switch o {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opRem:
		return 2
	case opNeg:
		return 3
	default: // opLParen
		return 0
	}
}

func binaryOp(c byte) (op, bool) {
	switch c {
	case '+':
		return opAdd, true
	case '-':
		return opSub, true
	case '*':
		return opMul, true
	case '/':
		return opDiv, true
	case '%':
		return opRem, true
	}
	return 0, false
}

func isBlank(c byte) bool { return c == ' ' || c == '\t' }
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// evaluator parses and evaluates expressions using an explicit-stack
// operator-precedence algorithm, so deeply nested input cannot exhaust the
// goroutine stack. Its stacks are reused across calls to avoid allocation.
type evaluator struct {
	values []int64
	ops    []op
}

// evaluate returns the value of line, or ok == false on any syntax or
// arithmetic error.
func (e *evaluator) evaluate(line []byte) (int64, bool) {
	e.values = e.values[:0]
	e.ops = e.ops[:0]

	expectOperand := true
	n := len(line)
	for i := 0; i < n; {
		c := line[i]
		if isBlank(c) {
			i++
			continue
		}
		if expectOperand {
			switch {
			case isDigit(c):
				var v int64
				for ; i < n && isDigit(line[i]); i++ {
					d := int64(line[i] - '0')
					if v > (math.MaxInt64-d)/10 {
						return 0, false
					}
					v = v*10 + d
				}
				e.values = append(e.values, v)
				expectOperand = false
				continue
			case c == '-':
				e.ops = append(e.ops, opNeg)
			case c == '(':
				e.ops = append(e.ops, opLParen)
			default:
				return 0, false
			}
		} else {
			if c == ')' {
				for len(e.ops) > 0 && e.top() != opLParen {
					if !e.reduce() {
						return 0, false
					}
				}
				if len(e.ops) == 0 {
					return 0, false // unbalanced ')'
				}
				e.ops = e.ops[:len(e.ops)-1]
			} else if o, ok := binaryOp(c); ok {
				// All binary operators are left-associative.
				for len(e.ops) > 0 && e.top().precedence() >= o.precedence() {
					if !e.reduce() {
						return 0, false
					}
				}
				e.ops = append(e.ops, o)
				expectOperand = true
			} else {
				return 0, false
			}
		}
		i++
	}

	if expectOperand {
		return 0, false // missing operand (or empty input)
	}
	for len(e.ops) > 0 {
		if e.top() == opLParen {
			return 0, false // unbalanced '('
		}
		if !e.reduce() {
			return 0, false
		}
	}
	if len(e.values) != 1 {
		return 0, false
	}
	return e.values[0], true
}

func (e *evaluator) top() op { return e.ops[len(e.ops)-1] }

// reduce applies the operator on top of the stack to the value stack. It
// reports false on an arithmetic error.
func (e *evaluator) reduce() bool {
	o := e.top()
	e.ops = e.ops[:len(e.ops)-1]

	if o == opNeg {
		last := len(e.values) - 1
		r, ok := checkedNeg(e.values[last])
		e.values[last] = r
		return ok
	}

	last := len(e.values) - 1
	lhs, rhs := e.values[last-1], e.values[last]
	e.values = e.values[:last]

	var r int64
	var ok bool
	switch o {
	case opAdd:
		r, ok = checkedAdd(lhs, rhs)
	case opSub:
		r, ok = checkedSub(lhs, rhs)
	case opMul:
		r, ok = checkedMul(lhs, rhs)
	case opDiv:
		r, ok = checkedDiv(lhs, rhs)
	case opRem:
		r, ok = checkedRem(lhs, rhs)
	}
	e.values[last-1] = r
	return ok
}

// Command calc is a 64-bit signed integer expression evaluator.
//
// It reads one expression per line from standard input and prints its value
// or "error". Lines that are empty or contain only spaces and tabs produce no
// output.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "calc:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}

	out := bufio.NewWriterSize(w, 64*1024)
	var ev evaluator
	var buf []byte

	for len(input) > 0 {
		line := input
		if i := bytes.IndexByte(input, '\n'); i >= 0 {
			line, input = input[:i], input[i+1:]
		} else {
			input = nil
		}

		if isBlankLine(line) {
			continue
		}
		if v, ok := ev.evaluate(line); ok {
			buf = strconv.AppendInt(buf[:0], v, 10)
		} else {
			buf = append(buf[:0], "error"...)
		}
		buf = append(buf, '\n')
		if _, err := out.Write(buf); err != nil {
			return err
		}
	}
	return out.Flush()
}

func isBlankLine(line []byte) bool {
	for _, c := range line {
		if !isBlank(c) {
			return false
		}
	}
	return true
}
